package waf

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"goveto-edge/internal/policy"
)

// These tests lock in the WAF behavior that the benchmark matrix in
// script/run_agent_benchmark.sh depends on. They guard the contract between
// the benchmark policy generated by cmd/agent-bench-pki and the response
// status/headers the load generator asserts against.

// benchmarkWAFPolicy mirrors cmd/agent-bench-pki: DefaultWAFPolicy with the
// builtin-cc rate limiter disabled so a sustained throughput run does not flip
// clean responses to 429.
func benchmarkWAFPolicy(t *testing.T) policy.WAFPolicy {
	t.Helper()
	p := policy.DefaultWAFPolicy()
	for i := range p.RuleSets {
		if p.RuleSets[i].ID == "builtin-cc" {
			p.RuleSets[i].Enabled = false
		}
	}
	if err := p.NormalizeAndValidate(); err != nil {
		t.Fatalf("benchmark waf policy invalid: %v", err)
	}
	return p
}

func TestBenchmarkWAFPolicyCleanAndXSSPaths(t *testing.T) {
	h := provisionHandler(t, "benchmark-waf", benchmarkWAFPolicy(t))

	// Clean traffic: no rule matches, request passes through to the next handler
	// without an X-Goveto-WAF header.
	clean := httptest.NewRecorder()
	cleanReq := httptest.NewRequest(http.MethodGet, "/bytes/1024?waf_bench=clean", nil)
	next := &nextHandler{}
	if err := h.ServeHTTP(clean, cleanReq, next); err != nil {
		t.Fatal(err)
	}
	if clean.Code != http.StatusOK || next.calls != 1 {
		t.Fatalf("clean traffic: status=%d next=%d, want 200/1", clean.Code, next.calls)
	}
	if got := clean.Header().Get("X-Goveto-WAF"); got != "" {
		t.Fatalf("clean traffic set X-Goveto-WAF=%q, want absent", got)
	}

	// Malicious traffic: builtin-xss-query terminal block short-circuits the origin.
	blocked := httptest.NewRecorder()
	blockReq := httptest.NewRequest(http.MethodGet, "/bytes/1024?xss=%3Cscript%3Ealert(1)%3C/script%3E&waf_bench=block", nil)
	blockNext := &nextHandler{}
	if err := h.ServeHTTP(blocked, blockReq, blockNext); err != nil {
		t.Fatal(err)
	}
	if blocked.Code != http.StatusForbidden || blockNext.calls != 0 {
		t.Fatalf("xss traffic: status=%d next=%d, want 403/0", blocked.Code, blockNext.calls)
	}
	if got := blocked.Header().Get("X-Goveto-WAF"); got != "BLOCK" {
		t.Fatalf("xss traffic: X-Goveto-WAF=%q, want BLOCK", got)
	}
	if got := blocked.Header().Get("X-Goveto-WAF-Rule"); got != "builtin-xss-query" {
		t.Fatalf("xss traffic: X-Goveto-WAF-Rule=%q, want builtin-xss-query", got)
	}
}

func TestBenchmarkWAFBlockAllPolicy(t *testing.T) {
	// Mirrors the benchmark-waf-block site: an always-matching BLOCK rule that
	// terminates before the origin and writes a header-only 403 response.
	blockAll := policy.WAFPolicy{Enabled: true, RuleSets: []policy.WAFRuleSet{{
		ID: "benchmark-block", Name: "benchmark terminal block", Enabled: true,
		Rules: []policy.WAFRule{{
			ID: "benchmark-block-all", Name: "block all requests", Enabled: true,
			Type: policy.WAFRuleTypeMatch,
			Conditions: policy.WAFConditions{Operator: "AND", Groups: []policy.WAFConditionGroup{{
				Operator: "AND", Conditions: []policy.WAFCondition{{Field: "PATH", Operator: "PREFIX", Value: "/"}},
			}}},
			Action: policy.WAFAction{Type: policy.WAFActionBlock, StatusCode: http.StatusForbidden},
		}},
	}}}
	if err := blockAll.NormalizeAndValidate(); err != nil {
		t.Fatalf("benchmark block-all policy invalid: %v", err)
	}
	h := provisionHandler(t, "benchmark-waf-block", blockAll)
	rec := httptest.NewRecorder()
	next := &nextHandler{}
	if err := h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/bytes/1024?waf_bench=blockall", nil), next); err != nil {
		t.Fatal(err)
	}
	if rec.Code != http.StatusForbidden || next.calls != 0 {
		t.Fatalf("block-all: status=%d next=%d, want 403/0", rec.Code, next.calls)
	}
	if got := rec.Header().Get("X-Goveto-WAF"); got != "BLOCK" {
		t.Fatalf("block-all: X-Goveto-WAF=%q, want BLOCK", got)
	}
	if got := rec.Header().Get("X-Goveto-WAF-Rule"); got != "benchmark-block-all" {
		t.Fatalf("block-all: X-Goveto-WAF-Rule=%q, want benchmark-block-all", got)
	}
	if rec.Body.Len() != 0 {
		t.Fatalf("block-all wrote %d body bytes, want 0 (WAFActionBlock writes a header only): %q", rec.Body.Len(), rec.Body.String())
	}
}
